INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (1, '苏铁', NULL, 'Cycas revoluta Thunb.', '苏铁科', '苏铁属', '棕榈状常绿木本。树干高约2 m。羽状叶从茎的顶部生出，羽状叶呈倒卵状狭披针形，叶轴横切面四方状圆形，两侧有齿状刺；羽状裂片达100对以上，条形，厚革质，坚硬，向上斜展微成“V”形，边缘向下反卷，先端有刺状尖头。雄球花圆柱形，长30~70 cm，径8~15 cm，有短梗，小孢子叶窄楔形，长3.5~6 cm，顶端宽平，其两角近圆形，宽1.7~2.5 cm，有急尖头，尖头长约5 mm，直立；花药通常3个聚生；大孢子叶长14~22 cm，密生淡黄色或淡灰黄色绒毛，上部的顶片卵形至长卵形，边缘羽状分裂，裂片12~18对，胚珠2~6枚，生于大孢子叶柄的两侧，有绒毛。种子红褐色或橘红色，倒卵圆形或卵圆形，稍扁，密生灰黄色短绒毛。花期5~6月；果期9~10月。', '广西：桂林市广西植物研究所，25°04′58″N，110°17′58″E，159 m，2010-11-09，吴磊、吴望辉、农冬新4001101117。湖南：吉首大学，28°17′21″N，109°43′12″E，222 m，2011-09-03，徐亮、覃三立40019101170。四川：西昌川兴乡，27°52′30″N，102°19′28″E，2010-10-12，崔龙、李志强400211059。湖北：兴山县南阳镇，31°18′18″N，110°40′49″E，256 m，2012-08-29，危文亮，赵永国等400151177。生于海拔100~1000 m。产于福建、台湾、广东。日本也有分布。', '喜暖热湿润，不耐寒冷，生长甚慢。可采用种子繁殖、分蘖繁殖、切干繁殖和嫁接繁殖。种子繁殖：11~12月采集成熟种子，宜现采现播，初春播种，幼苗期应搭设遮阴棚，同时要防蚂蚁、甲虫危害。分蘖：采用植株中、下部萌生的吸芽为繁殖材料。切干：剪去叶片，将茎的中部横切成两段，置于阴凉处8~12 h，再栽入砂质土中。嫁接：用3~4年生以上的实生苗作砧木，用观赏价值极高的优良苏铁芽孢作接穗，砧木与接穗的直径相近，嫁接时间5~6月，解膜时间应推迟到翌年春、夏季。', '种子含油，茎含丰富的淀粉，微有毒，可供食用和药用，药用有治痢疾、止咳和止血之效；茎含淀粉，可供食用。树形优美，为优美的庭园观赏树种。', 1, 'PENDING');  -- 第1页 Cycas revoluta Thunb.
