INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (1, '湖北', '兴山县南阳镇', '31°18′18″N', '110°40′49″E', '256 m', '2012-08-29', '危文亮，赵永国等', '400151177', 4);  -- 苏铁 第1页 湖北兴山县南阳镇
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (2, '银杏', NULL, 'Ginkgo biloba L.', '银杏科', '银杏属', '乔木。短枝密被叶痕，亦可长出长枝；冬芽黄褐色，常为卵圆形，先端钝尖。叶扇形，有长柄，无毛，有多数叉状并列细纹；叶柄长3~10 cm，幼树及萌生枝上的叶常较大而深裂，有时裂片再分裂。球花雌雄异株，单性，生于短枝顶端的鳞片状叶的腋内，呈簇生状；雄球花柔荑花序状，下垂，雄蕊排列疏松，具短梗，花药常2个，长椭圆形；雌球花具长梗，梗端常分两叉，稀3~5裂或不分叉，每叉顶生一盘状珠座，胚珠着生其上，通常仅一个叉端的胚珠发育成种子。种子具长梗，下垂，常为椭圆形、长倒卵形、卵圆形或近圆球形，外种皮肉质，熟时黄色或橙黄色，外被白粉，有臭味；中种皮白色，骨质，具2~3条纵脊；内种皮膜质；胚乳肉质。花期3~4月；种子9~10月成熟。', '广西：桂林市广西师范大学，25°16′02″N，110°19′26″E，168m，2010-12-20，许为斌、吴望辉4001101159。河南：郑州惠济区，34°45′34″N，113°39′29″E，489 m，2011-10-05，王亚平、武振江、李丹凤400314052。江苏：徐州市泉山森林公园，34°13′02″N，117°09′28″E，53 m，2010-09-28，李宏庆、桂萍、熊申展4001171073。安徽：宣城市宁国县板桥自然保护区，30°31′57″N，118°38′51″E，267 m，2012-10-02，李星霖、刘巧霞、程志全4001171227；黄山猴园，30°04′18″N，118°08′27″E，540 m，2009-11-03，刘东明、戴建阅400111145。四川：峨边刘沟，29°17′183″N，103°30′446″E，2009-10-11，樊云川，王凯40021109069。湖北：房县白窝王家沟，32°07′00″N，110°47′20″E，2009-09-01，李晓东、杨林森40012131；竹山柳林，31°47′57″N，110°02′56″E，709 m，2010-11-01，李晓东、昝艳燕、罗曼曼400121118；神农架坪堑管理所，31°29′49.9″N，110°04′3″E，1387 m，2010-10-25，丁时东，危文亮等400151087。陕西：佛坪县西岔河三教殿，33°16′50″N，107°34′57″E，776 m，2009-08-09，薛帅400321059。北京：香山，40°00′05″N，116°11′41″E，154 m，2009-11-19，邢福武40011499。生于海拔500~1000m的天然林中，少见。产于浙江。', '适应性较强，喜光，不耐盐碱土及过湿的土壤。可采用分株、扦插、嫁接3种方法繁殖。分株：在2~3月进行，从壮龄雌株母树根蘖苗中分离4~5株健壮、多细根苗，移栽它处。扦插：在夏季进行，选采当年生的短枝，剪成7~10 cm的茎段，下切口削成马耳状斜面，基部浸水2 h后，扦插在蛭石沙床上，间歇喷雾水。嫁接：以盛果期健壮枝条为接穗，嫁接在实生苗上。防治银杏苗木茎腐病，可搭棚遮阴，降低土温；防治害虫可在冬季刮除树皮除虫卵，在6~7月人工摘除虫蛹，或用敌百虫或马拉松喷杀刚孵化的幼虫。', '种仁可入药；亦可炒食或作甜食，但不宜多吃，以防中毒；外种皮有防治植物病虫害之效。木材可供建筑、家具、器具、雕刻等用。也是优良的庭园树和行道树。', 2, 'PENDING');  -- 第2页 Ginkgo biloba L.
