INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (3, '云南黄果冷杉', NULL, 'Abies ernestii var. salouenensis (Bordères et Gaussen) W. C. Cheng et L.K.Fu', '松科', '冷杉属', '乔木。树皮暗灰色，纵裂成薄块状。大枝平展，树冠尖塔形；冬芽卵圆形或圆锥状卵圆形，有树脂。叶在枝条下面排成两列，上面之叶直立或斜上伸展，条形，弯镰状或直，不反曲，长1.5~3.5 cm，宽2~2.5 mm；果枝之叶长达4~7 cm，上面中脉凹下，多较明显。雌球花紫褐黑色。球果圆柱形或卵状圆柱形，有短梗或近无梗；中部种鳞宽倒三角状扇形、扇状四方形或肾状四边形，上部宽圆较薄，边缘内曲，中部收缩或微收缩，两侧薄，常突出，稀楔形，边缘有缺齿，下部圆截形，基部窄成短柄状，鳞背露出部分密生短柔毛；苞鳞短，上部圆；微凹或平，边缘有细缺齿，背面中上部有纵脊。种子斜三角形，种翅褐色或紫黑色，边缘有波状细缺齿，连同种子长1.5~2.7 cm。花期4~5月；球果10月成熟。', '云南：香格里拉，27°55′5″N，99°37′34″E，3494 m，2012-11-02，李晓东、昝艳燕等400121295。生于海拔2600~3200 m的林中。产于云南、西藏。', '喜冷湿气候，喜深厚、湿润、排水良好的酸性土。可采用播种繁殖。采用新鲜的种子沙藏1~3个月后播种。幼苗需遮阴。', '树皮可提栲胶。木材淡黄白色，质轻软、细密，纹理直，可作建筑、板材、家具、火柴杆及造纸原料等用材。', 3, 'PENDING');  -- 第3页 Abies ernestii var. salouenensis (Bordères et Gaussen) W. C. Cheng et L.K.Fu
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (3, 'page-03/fig-03.png', '枝叶（针叶）特写', NULL, 0, 1);  -- 第3页 枝叶（针叶）特写
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (3, 'page-03/fig-04.png', '植株（大树）', NULL, 1, 2);  -- 第3页 植株（大树）
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (3, '云南', '香格里拉', '27°55′5″N', '99°37′34″E', '3494 m', '2012-11-02', '李晓东、昝艳燕等', '400121295', 1);  -- 云南黄果冷杉 第3页 云南香格里拉
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (4, '巴山冷杉', NULL, 'Abies fargesii Franch.', '松科', '冷杉属', '乔木。冬芽卵圆形或近圆形，有树脂。叶在枝条下面排成两列，上面之叶斜展或直立，稀上面中央之叶向后反曲，条形，上部较下部宽，长1~3 cm，宽1.5~4 mm，直或微曲，先端钝有凹缺，稀尖，上面深绿色，有光泽，无气孔线，下面沿中脉两侧有2条粉白色气孔带；横切面上面至下面两侧边缘有1层连续排列的皮下细胞，稀两端角部2层，下面中部1层，树脂道2个中生。球果柱状矩圆形或圆柱形，成熟时淡紫色、紫黑色或红褐色；中部种鳞肾形或扇状肾形，上部宽厚，边缘内曲；苞鳞倒卵状楔形，上部圆，边缘有细缺齿，先端有急尖的短尖头，尖头露出或微露出。种子倒三角状卵圆形，种翅楔形。花期4~5月；果期9月。', '湖北：神农架小龙潭，31°28′51″N，110°18′09″E，2179 m，2010-02-10，李晓东、昝艳燕400121162。陕西：眉县营头乡大殿，34°01′51″N，107°25′14″E，2273 m，2009-08-07，薛帅400321031；安康市千家坪，32°00′08″N，109°12′10″E，2200 m，2012-10-12，秦烁、郭利磊400328032。生于海拔1500~3900 m的山地、河床。产湖北、河南、四川、甘肃、陕西。', '喜气候温凉湿润及石英岩等母质发育的酸性棕色森林土或山地棕色森林土，耐阴性强。可采用播种方法。', '可为更新造林树种。', 4, 'PENDING');  -- 第4页 Abies fargesii Franch.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (4, 'page-04/fig-01.png', '枝叶与球果（紫黑色）', NULL, 1, 1);  -- 第4页 枝叶与球果（紫黑色）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (4, 'page-04/fig-02.png', '树干（树皮）', NULL, 0, 2);  -- 第4页 树干（树皮）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (4, 'page-04/fig-03.png', '植株（大树）', NULL, 0, 3);  -- 第4页 植株（大树）
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (4, '湖北', '神农架小龙潭', '31°28′51″N', '110°18′09″E', '2179 m', '2010-02-10', '李晓东、昝艳燕', '400121162', 1);  -- 巴山冷杉 第4页 湖北神农架小龙潭
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (4, '陕西', '眉县营头乡大殿', '34°01′51″N', '107°25′14″E', '2273 m', '2009-08-07', '薛帅', '400321031', 2);  -- 巴山冷杉 第4页 陕西眉县营头乡大殿
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (4, '陕西', '安康市千家坪', '32°00′08″N', '109°12′10″E', '2200 m', '2012-10-12', '秦烁、郭利磊', '400328032', 3);  -- 巴山冷杉 第4页 陕西安康市千家坪
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (5, '杉松', NULL, 'Abies holophylla Maxim. [Abies yoneyamae K. Satô]', '松科', '冷杉属', '乔木。幼树树皮淡褐色，不开裂，老则浅纵裂，灰褐色；枝条平展；冬芽卵圆形，有树脂。叶条形，直伸或成弯镰状，长2~4 cm，宽1.5~2.5 mm，先端急尖或渐尖，上面深绿色，有光泽，下面沿中脉两侧各有1条白色气孔带。球果圆柱形，近无梗，熟时淡黄褐色或淡褐色；中部种鳞近扇状四边形或倒三角状扇形，上部宽圆、微厚，鳞背露出部分被密生短毛；苞鳞短，长不及种鳞的一半，不露出，先端有急尖的刺状尖头，背部有纵脊；种子倒三角状，种翅宽大，淡褐色，长方状楔形，边缘有细波状缺刻，连同种子长约2.4 cm。花期4~5月；果期10月。', '生于海拔500~1200 m的土层肥厚弱灰化棕色森林土地带。产东北地区山区。朝鲜、俄罗斯也有分布。', '喜冷湿气候，喜深厚、湿润、排水良好的酸性土，耐寒、耐阴。可采用播种、扦插繁殖。播种：采用新鲜的种子沙藏1~3个月后播种，幼苗需遮阴。扦插：宜冬季经生长激素处理，生根良好。宜定植于建筑物的背阴面。', '树皮可提栲胶。木材纹理直，耐腐力较强，可供建筑、电杆及木纤维工业原料等用材。可在建筑物北侧或其他树冠庇荫下栽植，也可在草坪上丛植成景。', 4, 'PENDING');  -- 第4页 Abies holophylla Maxim. [Abies yoneyamae K. Satô]
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (5, 'page-04/fig-04.png', '植株（幼树）', NULL, 0, 1);  -- 第4页 植株（幼树）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (5, 'page-04/fig-05.png', '植株（大树）', NULL, 1, 2);  -- 第4页 植株（大树）
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (6, '怒江冷杉', NULL, 'Abies nukiangensis C. Y. Cheng et L. K. Fu', '松科', '冷杉属', '乔木。冬芽圆球形，微具树脂。叶在枝条下面排成两列，枝条上面的叶斜展或两列状排列，条形，通常微弯，长1.2~4.3 cm，宽1.5~2.5 mm，边缘向下卷曲或微卷曲，先端有凹缺，基部微窄，上面深绿色，下面中脉两侧各有1条白粉气孔带。雄球花长约2.5 cm，下垂，雄蕊的药隔二叉状，先端尖。球果圆柱形，上部微窄，熟时黑色，微被白粉；中部种鳞扇状四边形，上部较厚，边缘内曲，中部楔状，下部两侧耳状，基部窄成短柄状；苞鳞不露出，顶端圆或宽圆，边缘有细缺齿。种子较种翅为长，种翅淡黑褐色或红褐色，楔形，上端截形，宽约9 mm，连同种子长1.6~1.9 cm。', '云南：丽江市宁蒗县，27°17′8″N，100°51′2″E，2248 m，2008-10-29，张国学400222038。生于海拔2500~3100 m的地带。产于云南。印度、缅甸及越南亦有分布。', '喜冷湿气候，喜深厚、湿润、排水良好的酸性土。可采用播种、扦插繁殖。播种：采用新鲜的种子沙藏1~3个月后播种，幼苗需遮阴。扦插：宜冬季经生长激素处理，生根良好。宜定植于建筑物的背阴面。', '树皮可提栲胶。木材淡黄白色，质轻软、细密，纹理直，可供建筑、板材、家具、火柴杆及造纸原料等用材。', 5, 'PENDING');  -- 第5页 Abies nukiangensis C. Y. Cheng et L. K. Fu
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (6, 'page-05/fig-01.png', '种子（带翅）堆置特写', NULL, 1, 1);  -- 第5页 种子（带翅）堆置特写
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (6, 'page-05/fig-02.png', '种子与手写采集标签（编号0042）', NULL, 0, 2);  -- 第5页 种子与手写采集标签（编号0042）
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (6, '云南', '丽江市宁蒗县', '27°17′8″N', '100°51′2″E', '2248 m', '2008-10-29', '张国学', '400222038', 1);  -- 怒江冷杉 第5页 云南丽江市宁蒗县
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (7, '雪松', NULL, 'Cedrus deodara (Roxb.) G. Don', '松科', '雪松属', '乔木。树皮深灰色，裂成不规则的鳞状块片；枝平展、微斜展或微下垂。叶在长枝上辐射状伸展，长2.5~5 cm，宽1~1.5 mm，上部较宽，先端锐尖，下部渐窄，常成三棱形，稀背脊明显，叶之腹面两侧各有2~3条气孔线，背面4~6条，幼时气孔线有白粉。雄球花长卵圆形或椭圆状卵圆形；雌球花卵圆形。球果成熟前淡绿色，微有白粉，熟时红褐色，卵圆形或宽椭圆形，顶端圆钝，有短梗；中部种鳞扇状倒三角形，上部宽圆，边缘内曲，中部楔状，下部耳形，基部爪状，鳞背密生短绒毛；苞鳞短小。种子近三角状，种翅宽大，较种子为长，连同种子长2.2~3.7 cm。', '山东：诸城，35°59′34″N，119°24′36″E，52 m，2010-06-10，赵伟华400311221。生于海拔1300~3300 m的地带。产于西藏。北京、旅顺、大连、青岛、徐州、上海、南京、杭州、南平、庐山、武汉、长沙、昆明等地有栽培。', '喜阳光充足、气候温和凉润，适宜土层深厚、排水良好的酸性土，也稍耐阴。可采用播种和扦插繁殖。播种：可于3月中下旬进行，播种量为75 kg/hm²。扦插：在春、夏两季均可进行。春季宜在3月20日前，夏季以7月下旬为佳。可喷洒苯来特或代森锌防治灰霉病，喷洒氧化乐果、敌百虫等防治蚧类及蛾蝶类害虫。', '材质坚实，有树脂，具香气，耐久用，可作建筑、桥梁、造船、家具及器具等用材。树形美观，为优良的庭园观赏树种。', 5, 'PENDING');  -- 第5页 Cedrus deodara (Roxb.) G. Don
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (7, 'page-05/fig-03.png', '雄球花（黄色）簇生枝上', NULL, 1, 1);  -- 第5页 雄球花（黄色）簇生枝上
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (7, 'page-05/fig-04.png', '幼小球果（绿色）着生枝上', NULL, 0, 2);  -- 第5页 幼小球果（绿色）着生枝上
