INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (7, '山东', '诸城', '35°59′34″N', '119°24′36″E', '52 m', '2010-06-10', '赵伟华', '400311221', 1);  -- 雪松 第5页 山东诸城
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (8, '铁坚油杉', NULL, 'Keteleeria davidiana (Bertr.) Beissn.', '松科', '油杉属', '乔木。一年生枝淡黄灰色；冬芽卵圆形，先端微尖。叶条形，在侧枝上排列成两列，长2~5 cm，宽3~4 mm，先端圆钝或微凹，基部渐窄成短柄，上面光绿色，无气孔线或中上部有极少的气孔线，下面淡绿色，沿中脉两侧各有气孔线10~16条，微有白粉，横切面上面有1层不连续排列的皮下层细胞；幼树或萌生枝有密毛，叶较长。球果圆柱形；中部的种鳞卵形或近斜方状卵形，上部圆或窄长而反曲，边缘向外反曲，有微小的细齿，鳞背露出部分无毛或疏生短毛；鳞苞上部近圆形，先端3裂，中裂窄，鳞苞中部窄短，下部稍宽；种翅中下部或近中部较宽，上部渐窄。花期4月；果期10月。', '生于海拔600~1500 m地带。产于湖南、湖北、四川、贵州、甘肃、陕西。', '喜光，喜温暖湿润。可采用播种繁殖。', '根皮油脂可作造纸填料。木材可作房屋建筑、桥梁及一般用具等用材。', 6, 'PENDING');  -- 第6页 Keteleeria davidiana (Bertr.) Beissn.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (8, 'page-06/fig-01.png', '枝叶（针叶与枝条）', NULL, 1, 1);  -- 第6页 枝叶（针叶与枝条）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (8, 'page-06/fig-02.png', '植株全形（大树）', NULL, 0, 2);  -- 第6页 植株全形（大树）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (8, 'page-06/fig-03.png', '针叶特写', NULL, 0, 3);  -- 第6页 针叶特写
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (9, '云南油杉', NULL, 'Keteleeria evelyniana Mast.', '松科', '油杉属', '乔木。一年生枝干后常呈粉红色，有毛。叶条形，在侧枝上排列成两列，长2~6.5 cm，宽2~3 mm，先端有微凸起的钝尖头，基部楔形，渐窄成短叶柄，上面光绿色，中脉两侧每边有2~10条气孔线，下面沿中脉两侧每边有14~19条气孔线。球果圆柱形；中部的种鳞卵状斜方形或斜方状卵形，长3~4 cm，宽2.5~3 cm，上部向外反曲，边缘有明显的细小缺齿，鳞背露出部分通常有毛；苞鳞中部窄，下部逐渐增宽，上部近圆形，先端呈不明显的3裂，中裂明显，侧裂近圆形；种翅中下部较宽，上部渐窄。花期4~5月；果期10月。', '生于海拔700~2600 m的地带。产于四川、贵州、云南。', '喜光，喜温暖湿润，耐火烧，耐寒、耐旱能力较差，对土壤要求较高，在腐殖质含量低、土壤板结黏重、肥力低的地方生长不良。可采用播种繁殖。', '种子榨油可用于制皂工业。木材可作建筑、家具等用材。', 6, 'PENDING');  -- 第6页 Keteleeria evelyniana Mast.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (9, 'page-06/fig-04.png', '雄球花（黄色）着生枝上', NULL, 1, 1);  -- 第6页 雄球花（黄色）着生枝上
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (9, 'page-06/fig-05.png', '树皮（纵裂）特写', NULL, 0, 2);  -- 第6页 树皮（纵裂）特写
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (9, 'page-06/fig-06.png', '植株全形（大树）', NULL, 0, 3);  -- 第6页 植株全形（大树）
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (10, '油杉', NULL, 'Keteleeria fortunei (A. Murray bis) Carrière', '松科', '油杉属', '乔木。一年生枝干后呈橘红色或淡粉红色；二、三年生时呈淡黄灰色，常不开裂。叶条形，在侧枝上排成两列，长1.2~3 cm，宽2~4 mm，先端圆或钝，基部渐窄，上面光绿色，无气孔线，下面淡绿色，沿中脉每边有气孔线12~17条。球果圆柱形，成熟前绿色或淡绿色，微有白粉，成熟时淡褐色或淡栗色；中部的种鳞宽圆形或上部宽圆下部宽楔形，上部宽圆或近平截，稀中央微凹，边缘向内反曲，鳞背露出部分无毛；鳞苞中部窄，下部稍宽，上部卵圆形，先端3裂，中裂窄长，侧裂稍圆，有钝尖头；种翅中上部较宽，下部渐窄。花期3~4月；果期10月。', '生于海拔400~1200 m的气候温暖、雨量多及酸性红壤或黄壤的地带。产于广东、广西、福建、浙江。', '适应性强，喜光，耐干旱瘠薄。可采用播种繁殖。种子可随采随播，亦可用湿沙层积贮藏至翌年2月春播，苗期喜光，但在7、8月间需短期遮阴。', '种子油为不干性油，可制肥皂和润滑油。木材坚实耐用，供建筑、家具等用材。可作园林树种。', 7, 'PENDING');  -- 第7页 Keteleeria fortunei (A. Murray bis) Carrière
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (10, 'page-07/fig-01.png', '枝叶与幼球果（红色）', NULL, 1, 1);  -- 第7页 枝叶与幼球果（红色）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (10, 'page-07/fig-02.png', '球果（被白粉）特写', NULL, 0, 2);  -- 第7页 球果（被白粉）特写
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (11, '落叶松', NULL, 'Larix gmelinii (Rupr.) Kuzen.', '松科', '落叶松属', '乔木。一年生长枝较细，淡黄褐色或淡褐黄色，二、三年生枝褐色、灰褐色或灰色，短枝直径2~3 mm，顶端叶枕之间有黄白色长柔毛；冬芽近圆球形，芽鳞暗褐色，边缘具睫毛，基部芽鳞的先端具长尖头。球果幼时紫红色，成熟前卵圆形或椭圆形，成熟时上部的种鳞张开，黄褐色、褐色或紫褐色，种鳞14~30枚；中部种鳞五角状卵形，先端截形、圆截形或微凹，鳞背无毛，有光泽；苞鳞较短，近三角状长卵形或卵状披针形，先端具中肋延长的急尖头。种子斜卵圆形，灰白色，具淡褐色斑纹；种翅中下部宽，上部斜三角形，先端钝圆。花期5~6月；果期9月。', '黑龙江：北极村，53°28′10″N，122°24′7″E，174 m，2011-09-08，贾海伦400351107；大兴安岭塔河，52°20′07″N，124°42′31″E，410 m，2010-10-04，郑宝江、陶林40034016。生于海拔300~2800 m的山麓、沼泽、草甸、河谷。产于河南、河北、陕西、内蒙古、吉林、黑龙江。朝鲜、蒙古、俄罗斯也有分布。', '适应性强，喜光，喜冷凉气候，耐寒，耐干旱瘠薄，有一定的耐水湿能力。可采用播种繁殖。', '树干可提取树脂；树皮可提取栲胶。木材耐久用，可供土木工程、器具、枕木、电杆、造纸等用。树干通直挺拔，树姿优美，为珍贵的园林树和庭园观赏树种。', 7, 'PENDING');  -- 第7页 Larix gmelinii (Rupr.) Kuzen.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (11, 'page-07/fig-03.png', '枝叶与幼球果', NULL, 1, 1);  -- 第7页 枝叶与幼球果
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (11, 'page-07/fig-04.png', '成熟球果（褐色，种鳞张开）', NULL, 0, 2);  -- 第7页 成熟球果（褐色，种鳞张开）
