INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (11, '黑龙江', '大兴安岭塔河', '52°20′07″N', '124°42′31″E', '410 m', '2010-10-04', '郑宝江、陶林', '40034016', 2);  -- 落叶松 第7页 黑龙江大兴安岭塔河
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (12, '黄花落叶松', NULL, 'Larix olgensis A. Henry', '松科', '落叶松属', '乔木。枝平展或斜展，树冠塔形；冬芽淡紫褐色，顶芽卵圆形或微成圆锥状，芽鳞膜质，边缘具睫毛，基部芽鳞三角状卵形，先端有长尖头。叶倒披针状条形，长1.5~2.5 cm，宽约1 mm，先端钝或微尖，上面中脉平，种鳞16~40枚，背面及上部边缘有或密或疏的细小瘤状凸起，间或在近中部杂有短毛，稀近于光滑；中部种鳞广卵形常成四方状，或近方圆形，基部稍宽，先端圆或圆截形微凹，干后边缘常反曲；苞鳞暗紫褐色，矩圆状卵形或卵状椭圆形，中部稍收缩，先端圆截形或微凹，中肋延长成尾状尖头。种子近倒卵圆形，淡黄白色或白色；种翅先端钝尖。花期5月；果期9~10月。', '生于海拔500~1800 m的湿润山坡及沼泽地区。产于山西、辽宁、黑龙江。', '适应性强，对土壤和水、肥条件要求不高，喜光，耐严寒，喜湿润，有一定的耐旱、耐水湿能力。可采用播种繁殖。根系较浅，移植较难，易遭风害，栽植成活后，应进行培土。', '木材纹理直、结构细、耐久用，可作建筑、舰船、车辆、家具及木纤维工业原料等用材；树干可提树脂，树皮可提栲胶。可作庭园树、风景林树种。', 8, 'PENDING');  -- 第8页 Larix olgensis A. Henry
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (12, 'page-08/fig-01.png', '雪中枝叶（针叶覆雪）', NULL, 1, 1);  -- 第8页 雪中枝叶（针叶覆雪）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (12, 'page-08/fig-02.png', '球果（紫红色）着生枝上', NULL, 0, 2);  -- 第8页 球果（紫红色）着生枝上
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (12, 'page-08/fig-03.png', '植株全形（树形）', NULL, 0, 3);  -- 第8页 植株全形（树形）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (12, 'page-08/fig-04.png', '树干与树皮', NULL, 0, 4);  -- 第8页 树干与树皮
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (13, '云杉', NULL, 'Picea asperata Mast.', '松科', '云杉属', '乔木。一年生小枝通常淡褐黄色；冬芽圆锥形，有树脂，基部膨大。主枝之叶辐射状伸展，侧枝上面之叶向上伸展，下面及两侧之叶向上方弯伸，四棱状条形，微弯曲，先端微尖或急尖，横切面四棱形，四面有气孔线，上面每边4~8条，下面每边4~6条。球果圆柱状矩圆形或圆柱形，上端渐窄，成熟前绿色，熟时淡褐色或栗褐色；中部种鳞倒卵形，上部圆或截圆形则排列紧密，或上部钝三角形则排列较松，先端全缘，或球果基部或中下部种鳞的先端两裂或微凹；苞鳞三角状匙形，长约5 mm。种子倒卵圆形；种翅淡褐色，倒卵状矩圆形。花期4~5月；果期9~10月。', '湖北：神农架大九湖，31°28′50″N，109°58′18″E，1781 m，2010-10-15，李晓东、昝艳燕、罗曼曼400121131。四川：若尔盖县巴西乡林业站，33°36′22″N，103°14′12″E，2749 m，2009-07-22，干友民400241023。青海：祁连县，38°07′55″N，100°11′01″E，3156 m，2012-09-14，刘小波、曹弈璘等40021112002。生于海拔2400~3600 m的山地。产于四川、西藏、青海、甘肃、宁夏、陕西。', '适应性强，喜光、耐旱、耐寒凉。可采用播种、扦插繁殖。', '树干可取松脂，树皮可提取栲胶，木材、枝桠、根及叶均可用来提取芳香油。木材细致，材质轻软，有弹性，为良好用材。是一种理想的庭园观赏树种。', 8, 'PENDING');  -- 第8页 Picea asperata Mast.
INSERT INTO crop_aliases (crop_id, alias_name, alias_type) VALUES (13, '粗枝云杉', '中文别名');
