INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (13, '四川', '若尔盖县巴西乡林业站', '33°36′22″N', '103°14′12″E', '2749 m', '2009-07-22', '干友民', '400241023', 2);  -- 云杉 第8页 四川若尔盖县巴西乡林业站
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (13, '青海', '祁连县', '38°07′55″N', '100°11′01″E', '3156 m', '2012-09-14', '刘小波、曹弈璘等', '40021112002', 3);  -- 云杉 第8页 青海祁连县
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (14, '鱼鳞云杉', NULL, 'Picea jezoensis var. microsperma (Lindl.) W.C. Cheng et L. K. Fu', '松科', '云杉属', '乔木。一年生枝通常褐色，微有光泽，二、三年生枝微带灰色；冬芽圆锥形，淡褐色，几无树脂，芽鳞上部渐窄，排列较疏松，通常向外开展或微反曲，小枝基部宿存芽鳞的先端反卷或开展。小枝上面之叶覆瓦状向前伸展，下面及两侧之叶向两侧弯伸，条形，常微弯，长1~2 cm，宽1.5~2 mm，先端常微钝，上面有2条白粉气孔带，每带有5~8条气孔线，下面光绿色，无气孔。球果矩圆状圆柱形或长卵圆形，成熟前绿色，熟时褐色或淡黄褐色；种鳞薄，排列疏松，中部种鳞卵状椭圆形或菱状椭圆形，中部较宽，先端近截形或圆，边缘有不规则细缺齿，基部宽楔形微圆；苞鳞先端凸尖或圆。种子连翅长约9 mm，种翅宽约3.5 mm。花期5~6月；果期9~10月。', '生于海拔300~800 m气候寒凉、棕色森林土的丘陵或缓坡地带。产于东北大兴安岭至小兴安岭南端及松花江流域中下游。日本、俄罗斯也有分布。', '喜阴，耐低温严寒，不耐干旱、瘠薄、盐碱。可采用播种繁殖。种子催芽多采取混雪埋藏、混沙埋藏催芽或温水浸种催芽，多采取春播。易受日灼和立枯病危害。', '种子含油率高，供工业用；树皮可提栲胶，树干可割取松脂；叶可提取芳香油；木材纹理直，结构细，不易开裂，耐久用，可供建筑、飞机、桥梁及木纤维工业等用材。', 9, 'PENDING');  -- 第9页 Picea jezoensis var. microsperma (Lindl.) W.C. Cheng et L. K. Fu
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (14, 'page-09/fig-01.png', '枝叶与球果', NULL, 1, 1);  -- 第9页 枝叶与球果
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (14, 'page-09/fig-02.png', '树干与树皮', NULL, 0, 2);  -- 第9页 树干与树皮
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (15, '红皮云杉', NULL, 'Picea koraiensis Nakai', '松科', '云杉属', '乔木。一年生枝黄色、淡黄褐色或淡红褐色，二、三年生枝淡黄褐色、褐黄色或灰褐色；冬芽圆锥形，上部芽鳞常向外展，小枝基部宿存，芽鳞的先端向外反曲。叶四棱状条形，主枝之叶近辐射状排列。球果卵状圆柱形或长卵状圆柱形，成熟前绿色，熟时绿黄褐色至褐色；中部种鳞倒卵形或三角状倒卵形，鳞背露出部分微有光泽，平滑，无明显的条纹；苞鳞条状，长约5 mm，中下部微窄，先端钝或微尖，边缘有极细的小缺齿。种子灰黑褐色，倒卵圆形；种翅淡褐色，倒卵状矩圆形，先端圆。花期5~6月；果期9~10月。', '黑龙江：桦川县申家店，46°34′06″N，130°37′39″E，673 m，2010-08-13，陈连江、卞勇、贾海伦400351030。生于海拔400~1800 m的山地。产于辽宁、吉林、黑龙江。朝鲜、俄罗斯也有分布。', '喜深厚、湿润土壤，较耐阴。可采用扦插、播种繁殖。扦插：在早春抽出新梢后，剪15 cm长插穗，在塑料大棚内进行扦插。播种：种子用雪藏法贮藏，春季播种前1周左右将种子取出，并混以湿沙播种。', '树冠塔形，树姿优美，是一种理想的园林观赏植物。', 9, 'PENDING');  -- 第9页 Picea koraiensis Nakai
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (15, 'page-09/fig-03.png', '树干与树皮', NULL, 1, 1);  -- 第9页 树干与树皮
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (15, 'page-09/fig-04.png', '植株全形', NULL, 0, 2);  -- 第9页 植株全形
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (15, 'page-09/fig-05.png', '未成熟球果（绿色）与枝叶', NULL, 0, 3);  -- 第9页 未成熟球果（绿色）与枝叶
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (15, '黑龙江', '桦川县申家店', '46°34′06″N', '130°37′39″E', '673 m', '2010-08-13', '陈连江、卞勇、贾海伦', '400351030', 1);  -- 红皮云杉 第9页 黑龙江桦川县申家店
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (16, '西伯利亚云杉', NULL, 'Picea obovata Ledeb.', '松科', '云杉属', '乔木。一、二年生或一至三年生枝黄色或淡褐黄色，有较密的腺头短毛，老枝渐变为灰色或深灰色；冬芽圆锥形，有树脂，淡褐黄色，芽鳞排列较密。小枝上面之叶向前伸展，小枝下面及两侧的叶向上弯伸，四棱状条形，多少弯曲，先端有急尖的短尖头，横切面四棱形或扁棱形，上面每边有微具白粉的气孔线5~7条，下面每边有4~5条。球果卵状圆柱形或圆柱状矩圆形，幼时紫色或黑紫色，熟前黄绿色常带紫色，熟时褐色；中部种鳞楔状倒卵形，上部圆或截圆形，倒三角状卵圆形，连翅长1.4~1.6 cm；种翅褐色，倒卵状矩圆形。花期5月；果期9~10月。', '新疆：阿勒泰喀纳斯至哈巴河S229途中，48°35′50″N，86°41′15″E，1439 m，2011-09-19，侯翼国、王茜4003311037。生于海拔1200~1800 m的山地、山坡、河谷。产于新疆。哈萨克斯坦、蒙古、俄罗斯也有分布。', '耐阴，耐寒性强，喜湿润、肥沃、排水良好的酸性灰色森林土。可采用播种繁殖。幼苗期应注意遮阴、合理施肥，应及时灌水或浇水。', '树皮可提栲胶。材质细，纹理直，供建筑、造纸用，亦可作家具、电线杆等。', 10, 'PENDING');  -- 第10页 Picea obovata Ledeb.
INSERT INTO crop_aliases (crop_id, alias_name, alias_type) VALUES (16, '新疆云杉', '中文别名');
