INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (16, 'page-10/fig-02.png', '种子', NULL, 0, 2);  -- 第10页 种子
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (16, 'page-10/fig-03.png', '生境（云杉林）', NULL, 0, 3);  -- 第10页 生境（云杉林）
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (16, '新疆', '阿勒泰喀纳斯至哈巴河S229途中', '48°35′50″N', '86°41′15″E', '1439 m', '2011-09-19', '侯翼国、王茜', '4003311037', 1);  -- 西伯利亚云杉 第10页 新疆阿勒泰喀纳斯至哈巴河S229途中
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (17, '青扦', NULL, 'Picea wilsonii Mast.', '松科', '云杉属', '乔木。一年生枝淡黄绿色或淡黄灰色，无毛，稀有疏生短毛；冬芽卵圆形，无树脂，芽鳞排列紧密，淡黄褐色或褐色，先端钝，背部无纵脊，光滑无毛，小枝基部宿存芽鳞的先端紧贴小枝。叶排列较密，在小枝上部向前伸展，小枝下面之叶向两侧伸展，四棱状条形，直或微弯，较短，先端尖，横切面四棱形或扁棱形，四面各有气孔线4~6条，微具白粉。球果卵状圆柱形或圆柱状长卵圆形，成熟前绿色，熟时黄褐色或淡褐色；中部种鳞倒卵形，先端圆或有急尖头，或呈钝三角形，或具凸起截形之尖头，基部宽楔形；苞鳞匙状矩圆形，先端钝圆，长约4 mm。种子倒卵圆形，种翅倒宽披针形，淡褐色，先端圆。花期4月；果期10月。', '湖北：神农架大龙潭，31°29′37″N，110°18′03″E，2175 m，2010-11-10，李晓东、昝艳燕、罗曼曼400121127。生于海拔1400~2800 m的山地、河谷。产于湖北、四川、青海、甘肃、陕西、山西、河北、内蒙古。', '适应性较强，喜气候温凉，在土壤湿、深厚、排水良好的土壤生长良好。可采用播种繁殖。', '木材淡黄白色、纹理直，可供建筑、电杆、家具及工业原料等用材。', 10, 'PENDING');  -- 第10页 Picea wilsonii Mast.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (17, 'page-10/fig-04.png', '球果与枝叶', NULL, 1, 1);  -- 第10页 球果与枝叶
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (17, 'page-10/fig-05.png', '未成熟球果（绿色）与枝叶', NULL, 0, 2);  -- 第10页 未成熟球果（绿色）与枝叶
