INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (17, '湖北', '神农架大龙潭', '31°29′37″N', '110°18′03″E', '2175 m', '2010-11-10', '李晓东、昝艳燕、罗曼曼', '400121127', 1);  -- 青扦 第10页 湖北神农架大龙潭
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (18, '华山松', NULL, 'Pinus armandii Franch.', '松科', '松属', '乔木。一年生枝绿色或灰绿色，无毛；微被白粉。冬芽近圆柱形，褐色，微具树脂，芽鳞排列疏松。针叶5针一束，稀6~7针一束，长8~15 cm，径1~1.5 mm，边缘具细锯齿，仅腹面两侧各具4~8条白色气孔线，横切面三角形，树脂道通常3个，中生或背面2个边生、腹面1个中生；叶鞘早落。雄球花黄色，卵状圆柱形，基部围有近10枚卵状匙形的鳞片。球果圆锥状长卵圆形，幼时绿色，成熟时黄色或褐黄色，种鳞张开，种子脱落；中部种鳞近斜方状倒卵形；鳞盾近斜方形或宽三角状斜方形，不具纵脊，先端钝圆或微尖，不反曲或微反曲；鳞脐不明显。种子黄褐色、暗褐色或黑色，倒卵圆形，无翅或两侧及顶端具棱脊。花期4~5月；果期翌年9~10月。', '湖南：桑植县芭茅溪乡天平山，29°40′35″N，110°02′10″E，2009-10-22，张兵400181062；永顺小溪，29°25′20″N，109°25′22″E，324 m，2009-11-03，张代贵、周建军400191169。山东：泰山，36°15′37″N，117°07′15″E，910 m，2009-08-20，赵伟华400311057。河南：灵宝小秦岭，34°25′51″N，110°30′32″E，2413 m，2012-08-15，王亚平400314149。湖北：神农架红坪乡大沟，31°29′38″N，110°24′34″E，1835 m，2009-09-04，危文亮、丁时东400151003；神农架林区木鱼镇老君山，31°24′15″N，110°20′27″E，2508 m，2012-09-01，危文亮，赵永国等400151198；神农架红花朵大岩屋，31°49′05″N，110°29′40″E，2009-10-28，李晓东、杨林森40012175。四川：泸定县冷碛乡，29°51′11″N，102°15′22″E，2218 m，2009-08-24，干友民400241052。云南：麻栗坡县天保乡天保村芭蕉坪，22°58′07″N，104°50′36″E，1202 m，2008-10-29，张国学400222053。西藏：波密县扎木乡岗巴村，29°52′26″N，95°36′08″E，2791 m，2011-09-04，干友民40024132。陕西：眉县营头乡大殿，34°01′51″N，107°25′14″E，2273 m，2009-08-07，薛帅400321032。生于海拔1000~3300 m的山地、河谷。产于湖南、河南、湖北、四川、贵州、云南、西藏、甘肃、陕西、山西。', '喜温凉湿润气候，不耐寒及湿热，稍耐干燥、瘠薄。可采用播种繁殖。通常在播种前进行沙藏层积催芽，也可用50~60℃温水浸种催芽。幼苗出土前应保持土壤湿润并搭棚遮阴。用1:100波尔多液或50%多菌灵1000倍液喷施可防治立枯病。', '种子含油量高，可制硬化油和食用油等；种仁内富含蛋白质，常作干果炒食；树干可割取树脂，树皮可提取栲胶；针叶可提炼芳香油。木材可供建筑、家具及木纤维工业原料等用材。亦是较好的园林树种。', 11, 'PENDING');  -- 第11页 Pinus armandii Franch.
