INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (19, '白皮松', NULL, 'Pinus bungeana Zucc. ex Endl.', '松科', '松属', '乔木。幼树树皮光滑，灰绿色，长大后树皮成不规则的薄块片脱落，露出淡黄绿色的新皮。一年生枝灰绿色，无毛；冬芽红褐色，卵圆形，无树脂。针叶3针一束，粗硬，长5~10 cm，径1.5~2 mm，叶背及腹面两侧均有气孔线，先端尖，边缘有细锯齿；树脂道6~7个，边生；叶鞘脱落。雄球花卵圆形或椭圆形。球果通常单生，初直立，后下垂，成熟前淡绿色，熟时淡黄褐色，卵圆形或圆锥状卵圆形，有短梗或几无梗；种鳞矩圆状宽楔形，先端厚，鳞盾近菱形，有横脊，鳞脐生于鳞盾的中央，明显，三角状，顶端有刺。种子灰褐色，近倒卵圆形；种翅短，赤褐色。花期4~5月；果期翌年10~11月。', '生于海拔500~1800 m的地带。产于河南、四川、甘肃、陕西、山西。', '喜光，耐旱，耐瘠薄，抗寒力强，能适应钙质黄土及轻度盐碱土壤。可采用播种方法。播种宜在3月下旬至4月初，幼苗较耐阴，应搭建遮阴网，以防高温日灼和立枯病的危害。', '种子可榨油，供食用；木材可供房屋建筑、家具、文具等用材。树姿优美，为优良的庭园树种。', 12, 'PENDING');  -- 第12页 Pinus bungeana Zucc. ex Endl.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (19, 'page-12/fig-01.png', '枝叶与球果', NULL, 1, 1);  -- 第12页 枝叶与球果
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (19, 'page-12/fig-02.png', '植株全形', NULL, 0, 2);  -- 第12页 植株全形
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (20, '高山松', NULL, 'Pinus densata Mast.', '松科', '松属', '乔木。一年生枝粗壮，黄褐色，有光泽，无毛，二、三年生枝树皮逐渐脱落，内皮红色；冬芽卵状圆锥形或圆柱形，先端尖，微被树脂，芽鳞栗褐色。针叶2针一束，稀3针一束或2针3针并存，微扭曲，两面有气孔线，边缘锯齿锐利；叶鞘初呈淡褐色，老则暗灰褐色或黑褐色。球果卵圆形，长5~6 cm，径约4 cm，有短梗，熟时栗褐色，常向下弯垂；中部种鳞卵状矩圆形，鳞盾肥厚隆起，微反曲或不反曲，横脊显著，由鳞脐四周辐射状的纵横纹亦较明显，鳞脐凸起，多有明显的刺状尖头。种子淡灰褐色，椭圆状卵圆形，微扁；种翅淡紫色，长约2 cm。花期5月；果期翌年10月。', '四川：泸定定县冷碛乡二郎山，29°51′17″N，102°15′42″E，2719 m，2009-11-08，干友民400241065。云南：昆明市东郊呼马山，25°01′08″N，102°44′24″E，1946 m，2009-11-11，张国学400222079。生于海拔2600~3500 m的高山。产于四川、云南、西藏、青海。', '喜光、深根性树种，能生于干旱瘠薄的环境。', '树干可割取树脂。木材较坚韧，质较细，富树脂，可作建筑、板材等用材。', 12, 'PENDING');  -- 第12页 Pinus densata Mast.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (20, 'page-12/fig-03.png', '球果（红色背景）', NULL, 1, 1);  -- 第12页 球果（红色背景）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (20, 'page-12/fig-04.png', '种子（红色背景）', NULL, 0, 2);  -- 第12页 种子（红色背景）
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (20, 'page-12/fig-05.png', '植株全形', NULL, 0, 3);  -- 第12页 植株全形
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (20, '四川', '泸定定县冷碛乡二郎山', '29°51′17″N', '102°15′42″E', '2719 m', '2009-11-08', '干友民', '400241065', 1);  -- 高山松 第12页 四川泸定定县冷碛乡二郎山
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (20, '云南', '昆明市东郊呼马山', '25°01′08″N', '102°44′24″E', '1946 m', '2009-11-11', '张国学', '400222079', 2);  -- 高山松 第12页 云南昆明市东郊呼马山
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (21, '赤松', NULL, 'Pinus densiflora Sieb.', '松科', '松属', '乔木。一年生枝淡黄色或红黄色，微被白粉，无毛；冬芽矩圆状卵圆形，暗红褐色，微具树脂，芽鳞条状披针形，先端微反卷。针叶2针一束，先端微尖，两面有气孔线，边缘有细锯齿；横切面半圆形，皮下层细胞1层，稀角上2~3层，树脂道4~6个，边生。雄球花淡红黄色，圆筒形；雌球花淡红紫色，单生或2~3个聚生，一年生小球果的种鳞先端有短刺。球果成熟时暗黄褐色或淡褐黄色，种鳞张开，不久即脱落，卵圆形或卵状圆锥形，有短梗；种鳞薄，鳞盾扁菱形，通常扁平，稀具微隆起的横脊，鳞脐平或微凸起有短刺，稀无刺。种子倒卵状椭圆形或卵圆形，连翅长1.5~2 cm；种翅宽5~7 mm。花期4月；果期翌年9~10月。', '生于海拔0~920 m的山区。产于江苏、山东及东北地区。朝鲜、日本、俄罗斯也有分布。', '喜光，耐贫瘠，耐寒，耐干旱，不耐盐碱，抗风力强。可采用播种繁殖。', '种子榨油，可供食用及工业用；针叶提取芳香油；树干可割取树脂，提取松香及松节油。木材纹理直，质坚硬，耐腐力强，可供建筑、电杆、枕木、家具、木纤维工业原料等用。可作庭园树种。', 13, 'PENDING');  -- 第13页 Pinus densiflora Sieb.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (21, 'page-13/fig-01.png', '针叶与红色幼球果（雄球花）特写', NULL, 1, 1);  -- 第13页 针叶与红色幼球果（雄球花）特写
