INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (22, '湿地松', NULL, 'Pinus elliottii Engelm.', '松科', '松属', '乔木。树皮灰褐色或暗红褐色，纵裂成鳞状块片剥落；枝条每年生长3~4轮，春季生长的节间较长，夏、秋季生长的节间较短，小枝粗壮，橙褐色，后变为褐色至灰褐色，鳞叶上部披针形，淡褐色，边缘有睫毛，干枯后宿存数年不落，故小枝粗糙；冬芽圆柱形，上部渐窄，无树脂，芽鳞淡灰色。针叶2~3针一束并存，刚硬，深绿色，有气孔线，边缘有锯齿，树脂道2~9个，多内生。球果圆锥形或窄卵圆形，有梗，种鳞张开后径5~7 cm，成熟后至第二年夏季脱落；种鳞的鳞盾近斜方形，肥厚，有锐横脊，鳞脐瘤状。种子卵圆形，黑色，有灰色斑点，易脱落。花期3月；果期翌年9月。', '江西：石城县赣江源，26°11′36″N，116°23′16″E，547 m，2012-11-12，凡强、潘云云4001416090。原产美国。中国广东、广西、湖南、江西、福建、台湾、浙江、江苏、安徽、湖北、云南有栽培。', '适应性强，喜温暖潮湿、夏季炎热多雨、春季温暖干燥、冬季温和而潮湿的地区。可采用播种繁殖。播种：在10月份采收，放在干燥的地方贮藏，待翌年2月底至3月初进行播种。种子刚出苗时，使用托布津喷洒苗床预防猝倒病。', '种子含脂肪油可食用，亦可供药用；球果未成熟前，含挥发油，可提制松节油；蒸油后还可提炼栲胶；成熟球果制活性炭；松针含芳香油，是医药及化工、橡胶、造纸工业的原料。木材纹理直，供建筑、家具、造纸和木纤维工业原料用；林龄达20年左右的树干，适宜采割松脂，供提取松节油和松香，为工业和医药原料；树根挖取干馏，可提取松根原油；萃取可直接得松香、松节油。', 13, 'PENDING');  -- 第13页 Pinus elliottii Engelm.
