INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (23, '红松', NULL, 'Pinus koraiensis Sieb. et Zucc.', '松科', '松属', '乔木。一年生枝密被黄褐色或红褐色柔毛；冬芽淡红褐色，矩圆状卵圆形，先端尖，微被树脂，芽鳞排列较疏松。针叶5针一束，长6~12 cm，粗硬，直，深绿色，边缘具细锯齿，背面通常无气孔线；叶鞘早落。雄球花椭圆状圆柱形，红黄色；雌球花绿褐色，圆柱状卵圆形，直立。球果圆锥状卵圆形、圆锥状长卵圆形或卵状矩圆形，成熟后种鳞不张开，或稍微张开而露出种子；种鳞菱形，上部渐窄而开展，先端钝，向外反曲；鳞盾黄褐色或微带灰绿色，三角形或斜方状三角形，表面有皱纹；鳞脐不显著。种子大，着生于种鳞腹面下部的凹槽中，无翅或顶端及上部两侧微具棱脊，暗紫褐色或褐色，倒卵状三角形。花期6月；果期翌年9~10月。', '山西：翼城县历山，35°18′38″N，111°33′19″E，1782 m，2010-10-13，谢光辉400322011。黑龙江：伊春市嘉荫县八字山，48°16′05″N，129°31′03″E，1102 m，2010-08-18，陈连江、卞勇、贾海伦400351064。生于海拔200~1800 m的山地。产于山西、吉林、黑龙江。日本、朝鲜、俄罗斯也有分布。', '喜弱光，喜冷凉湿润气候及酸性土。可采用播种繁殖。播种前一般要经过浸种、消毒、催芽3个过程。', '种子又名松子，既是重要的中药，又可食用，可做糖果、糕点辅料，还可代植物油食用；松子油，除可食用外，还是干漆、皮革工业的重要原料。树干高大通直，树姿优美，可作为园林树种。', 14, 'PENDING');  -- 第14页 Pinus koraiensis Sieb. et Zucc.
