INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (23, '黑龙江', '伊春市嘉荫县八字山', '48°16′05″N', '129°31′03″E', '1102 m', '2010-08-18', '陈连江、卞勇、贾海伦', '400351064', 2);  -- 红松 第14页 黑龙江伊春市嘉荫县八字山
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (24, '华南五针松', NULL, 'Pinus kwangtungensis Chun et Tsiang', '松科', '松属', '乔木。一年生枝淡褐色，老枝淡灰褐色或淡黄褐色；冬芽茶褐色，微有树脂。针叶5针一束，长3.5~7 cm，径1~1.5 mm，先端尖，边缘有疏生细锯齿，仅腹面每侧有4~5条白色气孔线，横切面三角形，皮下层由单层细胞组成，树脂道2~3个，背面2个边生，有时腹面1个中生或无；叶鞘早落。球果柱状矩圆形或圆柱状卵形，通常单生，熟时淡红褐色，微具树脂；种鳞楔状倒卵形；鳞盾菱形，先端边缘较薄，微内曲或直伸。种子椭圆形或倒卵形，长8~12 mm，连同种翅与种鳞近等长。花期4~5月；果期翌年10月。', '广东：乳源广东松小黄山，113°01′08″N，24°53′48″E，639 m，2012-11-06，王发国、于海玲400119217。重庆：南川区水江镇乐村林场，29°07′12″N，107°14′40″E，1413 m，2009-09-06，刘正宇等400231056。生于海拔500~1600 m的山脊、山坡、山顶。产于海南、广东、广西、湖南、贵州。', '适应性较强。可采用播种繁殖。圃地选择排水良好的缓坡山地。“清明”前后播种，播前消毒，浸种催芽，待胚根露白时播下，伏天适当遮阴。', '可割取树脂提炼松香与松节油。木材坚实耐用，可供房屋建筑、枕木、矿柱、家具等用。为优良的园林树，可作园林树种。', 14, 'PENDING');  -- 第14页 Pinus kwangtungensis Chun et Tsiang
