INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (24, '重庆', '南川区水江镇乐村林场', '29°07′12″N', '107°14′40″E', '1413 m', '2009-09-06', '刘正宇等', '400231056', 2);  -- 华南五针松 第14页 重庆南川区水江镇乐村林场
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (25, '马尾松', NULL, 'Pinus massoniana D. Don', '松科', '松属', '乔木。枝条淡黄褐色，无白粉，稀有白粉，无毛；冬芽卵状圆柱形或圆柱形，芽鳞边缘丝状，先端尖或成渐尖的长尖头，微反曲。针叶2针一束，稀3针一束，长12~20 cm，两面有气孔线，边缘有细锯齿，横切面皮下层细胞单型，第一层连续排列，第二层由个别细胞断续排列而成，树脂道4~8个，在背面边生；叶鞘初成褐色，后渐变成灰黑色，宿存。雄球花淡红褐色，圆柱形，聚生于新枝下部苞腋，穗状；雌球花单生或2~4个聚生于新枝近顶端，淡紫红色。一年生小球果圆球形或卵圆形，褐色或紫褐色，上部珠鳞的鳞脐具向上直立的短刺，下部珠鳞的鳞脐平钝无刺。球果卵圆形或圆锥状卵圆形，有短梗，下垂；中部种鳞近矩圆状倒卵形；鳞盾菱形，微隆起或平，横脊微明显；鳞脐微凹，无刺，生于干燥环境者常具极短的刺。种子长卵圆形。花期4~5月；果期翌年10~12月。', '广东：阳山县秤架乡太平洞，24°55′48″N，112°59′07″E，2010-10-22，王发国、陈林400113062。湖南：保靖县白云山，28°37′51″N，109°17′16″E，398 m，2012-08-05，张代贵、张洁40019101262。湖北：鹤峰县太平乡肖家坪，29°49′28″N，109°54′55″E，937 m，2009-09-07，赵永国、丁时东400151042。四川：泸定泸桥镇，29°54′4″N，102°13′44″E，2010-11-11，崔龙、李志强40021110098；雅安宝兴蜂桶寨邓池沟，30°32′7″N，102°56′26″E，1789 m，2011-09-28，李志强、刘小波等40021111015。生于海拔2000 m以下的山地、平原。产于广东、广西、湖南、江西、福建、台湾、浙江、江苏、安徽、河南、湖北、四川、贵州、云南、陕西。', '喜光树种，不耐阴蔽，喜温。可采用播种繁殖。播种季节在2月上旬至3月上旬。马尾松毛虫是常见害虫，目前有白僵菌、Bt、仿生农药灭幼脲等适时施用。', '松籽含油率高，除食用外，可制肥皂、油漆及润滑油等；球果可提炼原油；松根可提取松焦油，也可培养贵重的中药材茯苓。松香是许多轻、重工业的重要原料，主要用于造纸、橡胶、涂料、油漆、胶黏等工业。松节油可合成松油，加工树脂，合成香料，生产杀虫剂，并为许多贵重萜烯香料的合成原料。松针含有挥发油，可提取松针油，供作清凉喷雾剂、皂用香精及配制其他合成香料，还可浸提栲胶；树皮可制胶黏剂和人造板。树干通直，可孤植或丛植作园林树，也是荒山造林先锋树种。', 15, 'PENDING');  -- 第15页 Pinus massoniana D. Don
