INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (26, '台湾五针松', NULL, 'Pinus morrisonicola Hayata [Pinus formosana Hayata; Pinus taiwanensis Hayata]', '松科', '松属', '乔木。树皮深灰褐色，裂成不规则鳞状厚块片或薄片。枝平展，老树树冠平顶，一年生枝淡黄褐色或暗红褐色，无毛，不被白粉；冬芽深褐色，卵圆形或长卵圆形，顶端尖，微有树脂，芽鳞先端尖，边缘薄，有细缺裂。针叶2针一束，边缘有细锯齿，两面有气孔线，横切面半圆形，树脂道3~7（9）个，中生；叶鞘宿存。雄球花圆柱形，淡红褐色，聚生于新枝下部成短穗状。球果卵圆形，几无梗，向下弯垂，成熟前绿色，熟时褐色或暗褐色，后渐变呈暗灰褐色，常宿存树上6~7年；中部种鳞近矩圆形，近鳞盾下部稍窄，基部楔形；鳞盾稍肥厚隆起，近扁菱形，横脊显著；鳞脐具短刺。种子倒卵状椭圆形，具不规则的红褐色斑纹。花期4~5月；果期翌年10月。', '江西：铅山县武夷山自然保护区，27°57′31″N，117°50′31″E，1317 m，2011-10-16，凡强、景慧娟4001411050。生于海拔600~3400 m的暖温带季雨林中。产于广西、湖南、江西、福建、台湾、浙江、江苏、安徽、河南、湖北、贵州、云南。', '喜光，喜凉润、湿度较大的高山气候，耐贫瘠，在土层深厚、排水良好的酸性土及向阳山坡生长良好。可采用播种繁殖。“春分”前后播种，每667 m²播种5~6 kg。', '木材纹理直，结构粗，富含树脂，耐水湿，为矿柱、枕木、码头、桥梁等用材；成年树可采割松脂，松枝、针叶为水泥袋纸和人造纤维原料；松针还可提取芳香油及医用胡萝卜素；采伐后的根桩可培养茯苓，供作中药和食用；花药可掺入糕点食用，并为痱子粉的优良配料；还可制成保健饮料和化妆品。为庭园观赏树种，亦作盆景栽培。', 16, 'PENDING');  -- 第16页 Pinus morrisonicola Hayata [Pinus formosana Hayata; Pinus taiwanensis Hayata]
