INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (27, '新疆五针松', NULL, 'Pinus sibirica Du Tour', '松科', '松属', '乔木。树冠塔形。大枝近水平开展，小枝粗壮，淡褐色，密被淡黄色柔毛；冬芽圆锥形，淡褐或红褐色，先端尖。针叶5针一束，较粗短，长7~12 cm，粗0.8~1.2 mm，边缘疏生细齿，背面无气孔线，腹面每边具3~5条气孔线，横断面近三角形，树脂道3个，中生；叶鞘早落。雌球果圆锥状卵形，无柄，直立，长6~10 cm，径5~6 cm，不开裂。种鳞宽楔形，内弯；鳞盾紫褐色，宽菱形，密生细绒毛，上部圆，微内曲，基部近平截；鳞脐黄褐色，明显。种子倒卵圆形，黄褐色，长1 cm，径5~6 mm，微具棱脊，无翅。花期5月；果期翌年8~9月。', '新疆：阿勒泰白哈巴，48°39′39″N，86°43′47″E，1726 m，2010-09-08，王喜勇、段士民4003310008；阿勒泰喀纳斯自然保护区，48°45′00″N，86°56′01″E，1715 m，2011-09-18，侯翼国、王茜4003311034。生于海拔800~2400 m的山地、河谷。产于新疆、内蒙古、黑龙江。哈萨克斯坦、蒙古、俄罗斯也有分布。', '喜光、抗寒、抗旱，对空气温度要求较高。可采用播种繁殖。', '种子可食，亦可榨油。木材轻、结构细，有香气，耐久用，可供建筑和特殊用材，亦可作家具等。树形优美，可作庭园树种。', 16, 'PENDING');  -- 第16页 Pinus sibirica Du Tour
