INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (28, '樟子松', NULL, 'Pinus sylvestris var. mongolica Litv.', '松科', '松属', '乔木。一年生枝淡黄褐色，无毛，二、三年生枝呈灰褐色；冬芽褐色或淡黄褐色，长卵圆形，有树脂。针叶2针一束，硬直，常扭曲，长4~9 cm，很少达12 cm，径1.5~2 mm，先端尖，边缘有细锯齿，两面均有气孔线，横切面半圆形，微扁，维管束鞘呈横茧状，2维管束距离较远，树脂道6~11个，边生；叶鞘基部宿存，黑褐色。雄球花圆柱状卵圆形，长5~10 mm，聚生新枝下部，长3~6 cm；雌球花有短梗，淡紫褐色。球果卵圆形或长卵圆形，长3~6 cm，径2~3 cm，成熟前绿色，熟时淡褐灰色；中部种鳞的鳞盾多呈斜方形，纵脊横脊显著，肥厚隆起，多反曲；鳞脐呈瘤状凸起，有易脱落的短刺。种子黑褐色，长卵圆形或倒卵圆形，微扁。花期5~6月；果期翌年9~10月。', '内蒙古：额尔古纳，51°39′39″N，120°39′10″E，2012-10，郑宝江等400341225。黑龙江：塔河，52°20′50″N，124°42′09″E，2012-10，郑宝江等400341223；桦川县申家店，46°35′36″N，130°39′13″E，650 m，2010-08-13，陈连江、卞勇、贾海伦400351023。生于海拔400~1100 m的砂质山地。产于内蒙古、黑龙江。蒙古、俄罗斯也有其分布。', '适应性强、抗逆性强、耐寒性强、喜光。可采用播种繁殖。春播前用50~60℃温水浸种催芽。一般在4月中、下旬，播种前苗床表土要保持适度温润，如干燥应少量浇水，播后及时填压，以防芽干。', '树干可割树脂，提取松梨及松节油；树皮可提取栲胶。木材纹理直，可供建筑、家具等用材。可作庭园观赏和绿化树种，也是沙荒地带重要的固沙造林的优良树种。', 17, 'PENDING');  -- 第17页 Pinus sylvestris var. mongolica Litv.
