INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (29, '油松', NULL, 'Pinus tabuliformis Carr. [Pinus tabuliformis var. tabuliformis]', '松科', '松属', '乔木。小枝较粗，褐黄色，无毛；冬芽矩圆形，顶端尖，微具树脂，芽鳞红褐色，边缘有丝状缺裂。针叶2针一束，深绿色，粗硬，边缘有细锯齿，两面具气孔线，横切面半圆形，树脂道5~8个或更多，边生，多数生于背面，腹面有1~2个；叶鞘初呈淡褐色，后呈淡黑褐色。雄球花圆柱形，在新枝下部聚生成穗状。球果卵形或圆卵形，有短梗，向下弯垂，成熟前绿色，熟时淡黄色或淡褐黄色，常宿存树上近数年之久；中部种鳞近矩圆状倒卵形；鳞盾肥厚、隆起或微隆起，扁菱形或菱状多角形，横脊显著；鳞脐凸起有尖刺。种子卵圆形或长卵圆形，淡褐色有斑纹。花期4~5月；果期翌年10月。', '四川：若尔盖县巴西乡林场，33°41′17″N，103°22′17″E，2714 m，2009-07-23，干友民400241027。河北：昌黎，39°57′55″N，119°15′45″E，131 m，2010-10-03，徐兴友、韩宝强400313074。生于海拔100~2600 m的山地。产于山东、河南、四川、青海、甘肃、宁夏、陕西、山西、河北、内蒙古、辽宁、吉林。', '适应性强，喜光、耐瘠薄、抗寒、抗风。可采用播种繁殖。播种前应当用福尔马林或高锰酸钾对种子进行消毒。幼苗主要要防止冻害，有覆土、覆草、冬灌及覆盖塑料薄膜防寒等方法。', '树干可割取松脂，提取松节油。树皮可提取栲胶，松节、针叶及花粉可入药。木材富含松脂，耐腐，供作建筑、家具、枕木、矿柱、电杆、人造纤维等用材，亦可采松脂供工业用。树形美观，茎干苍劲有力，可作园林树种。', 17, 'PENDING');  -- 第17页 Pinus tabuliformis Carr. [Pinus tabuliformis var. tabuliformis]
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (29, 'page-17/fig-05.png', '球果与针叶', NULL, 1, 1);  -- 第17页 球果与针叶
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (29, 'page-17/fig-06.png', '树干与树皮', NULL, 0, 2);  -- 第17页 树干与树皮
