INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (29, '河北', '昌黎', '39°57′55″N', '119°15′45″E', '131 m', '2010-10-03', '徐兴友、韩宝强', '400313074', 2);  -- 油松 第17页 河北昌黎
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (30, '黑松', NULL, 'Pinus thunbergii Parl.', '松科', '松属', '乔木。一年生枝淡褐黄色，无毛；冬芽银白色，圆柱状椭圆形或圆柱形，顶端尖，芽鳞披针形或条状披针形，边缘白色丝状。针叶2针一束，深绿色，有光泽，粗硬，长6~12 cm，径1.5~2 mm，边缘有细锯齿，背腹面均有气孔线，横切面皮下层细胞1层或2层，连续排列，树脂道6~11个，中生。雄球花淡红褐色，圆柱形，聚生于新枝下部；雌球花单生或2~3个聚生于新枝近顶端，直立，有梗，卵圆形，淡紫红色或淡褐红色。球果成熟前绿色，熟时褐色，圆锥状卵圆形或卵圆形，长4~6 cm，径3~4 cm，有短梗，向下弯垂；中部种鳞卵状椭圆形；鳞盾微肥厚，横脊显著；鳞脐微凹，有短刺。种子倒卵状椭圆形；种翅灰褐色，有深色条纹。花期4~5月；果期翌年10月。', '原产于日本及朝鲜海岸地区。中国辽宁、江苏、山东、浙江有栽培。', '喜光，耐寒冷，耐干旱、瘠薄及盐碱土，不耐水涝，抗病虫能力强。可采用播种繁殖。', '种子可榨油供工业用。木材结构较细、纹理直、耐久用，可作建筑、矿柱、器具等用材。可作园林及庭园树种。', 18, 'PENDING');  -- 第18页 Pinus thunbergii Parl.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (30, 'page-18/fig-01.png', '针叶与球果', NULL, 1, 1);  -- 第18页 针叶与球果
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (30, 'page-18/fig-02.png', '庭园中的植株', NULL, 0, 2);  -- 第18页 庭园中的植株
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (31, '云南松', NULL, 'Pinus yunnanensis Franch.', '松科', '松属', '乔木。一年生枝粗壮，淡红褐色，无毛，二、三年生枝上苞片状的鳞片脱落露出红褐色内皮；冬芽圆锥状卵圆形，粗大，红褐色，无树脂，芽鳞披针形。针叶通常3针一束，稀2针一束，常在枝上宿存3年，长10~30 cm，径约1.2 mm，先端尖，背腹面均有气孔线，边缘有细锯齿，横切面扇状三角形或半圆形，二型皮下层细胞，第一层细胞连续排列，其下有散生细胞，树脂道4~5个，中生与边生并存；叶鞘宿存。雄球花圆柱状，生于新枝下部的苞腋内，聚集成穗状。球果成熟前绿色，熟时褐色或栗褐色，圆锥状卵圆形，有短梗；中部种鳞矩圆状椭圆形；鳞盾通常肥厚、隆起、稀反曲，有横脊；鳞脐微凹或微隆起，有短刺。种子褐色，近卵圆形或倒卵形。花期4~5月；果期翌年10月。', '四川：泸定县老川藏线二郎山出洞口，29°51′10″N，102°15′21″E，2218 m，2009-08-24，干友民400241051；盐源莲花山，27°25′240″ N，101°30′291″ E，2009-10-05，樊云川、王凯40021109054。云南：昆明市东郊呼马山，25°01′38″N，102°44′03″E，1972 m，2008-10-29，张国学400222040。生于海拔600~3100 m的山地、河谷。产于广西、四川、贵州、云南、西藏。', '适应性强，喜光，耐干旱、耐瘠薄。可采用播种繁殖。用2.5敌百虫粉剂，每667 m²施3 kg喷粉可防治虫害。', '树根可培养茯苓，树干富含松脂，是制取松香松节油的原料；树皮可提取栲胶。针叶可提取松针油及加工成松针粉，作饲料添加剂；花粉可作药用，是美容护肤佳品。木材是优质造纸、人造板原料，并供建筑、家具等用材。可作为园林树种，同时为优良的荒山荒地造林先锋树种。', 18, 'PENDING');  -- 第18页 Pinus yunnanensis Franch.
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (31, 'page-18/fig-03.png', '针叶与球果', NULL, 1, 1);  -- 第18页 针叶与球果
