INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (31, '云南', '昆明市东郊呼马山', '25°01′38″N', '102°44′03″E', '1972 m', '2008-10-29', '张国学', '400222040', 3);  -- 云南松 第18页 云南昆明市东郊呼马山
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (32, '金钱松', NULL, 'Pseudolarix amabilis (J. Nelson) Rehd. [P. kaempferi Gordon]', '松科', '金钱松属', '乔木。一年生长枝淡红褐色或淡红黄色，无毛，有光泽，二、三年生枝淡黄灰色或淡褐灰色。叶条形，柔软，镰状或直，上部稍宽，长2~5.5 cm，宽1.5~4 mm，先端锐尖或尖，上面绿色，下面蓝绿色，中脉明显，每边有5~14条气孔线，气孔带较中脉带为宽或近于等宽。长枝之叶辐射状伸展，短枝之叶簇状密生。雄球花黄色，圆柱状；雌球花紫红色，直立，椭圆形，长约1.3 cm，有短梗。球果卵圆形或倒卵圆形，成熟前绿色或淡黄绿色，熟时淡红褐色，有短梗；中部的种鳞卵状披针形，基部宽约1.7 cm，两侧耳状，先端钝有凹缺；腹面种翅痕之间有纵脊凸起，脊上密生短柔毛，鳞背光滑无毛；苞鳞长为种鳞的1/4~1/3，卵状披针形，边缘有细齿。种子卵圆形，白色；种翅三角状披针形，淡黄色或淡褐黄色。花期4月；果期10月。', '江西：吉安市井冈山，26°33′26″N，114°09′17″E，160 m，2009-09-04，廖文波等400142007。生于常绿、落叶阔叶混交林中。产于湖南、江西、福建、浙江。', '喜温凉湿润气候。可采用播种、扦插繁殖。播种：为菌根性树种，宜在林间播种育苗，或用菌根土覆盖苗床，圃地适宜连作。扦插：利用10年生以下细枝条扦插，成活率可达70%。主要的病害有猝倒病、茎腐病和松落叶病，可用70%敌克松700倍液喷洒防治。主要虫害有袋蛾，除及时摘去袋囊外，对幼虫可用90%敌百虫1000倍液喷杀之。', '种子可榨油；根皮可治顽癣和食积等症；木材纹理直，耐水湿，为建筑、桥梁、船舶、家具等的优良用材。树姿优美，为著名的庭园树种。', 19, 'PENDING');  -- 第19页 Pseudolarix amabilis (J. Nelson) Rehd. [P. kaempferi Gordon]
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (32, 'page-19/fig-01.png', '枝叶特写', NULL, 1, 1);  -- 第19页 枝叶特写
INSERT INTO crop_images (crop_id, image_path, image_title, image_type, is_cover, sort_order) VALUES (32, 'page-19/fig-02.png', '植株', NULL, 0, 2);  -- 第19页 植株
INSERT INTO crop_distribution_points (crop_id, province, locality, latitude, longitude, altitude, collect_date, collectors, collection_no, sort_order) VALUES (32, '江西', '吉安市井冈山', '26°33′26″N', '114°09′17″E', '160 m', '2009-09-04', '廖文波等', '400142007', 1);  -- 金钱松 第19页 江西吉安市井冈山
INSERT INTO crops (id, chinese_name, english_name, latin_name, family, genus, features, distribution, cultivation, uses, source_page, review_status) VALUES (33, '柳杉', NULL, 'Cryptomeria fortunei Hooibr. ex Otto et Dietrich', '杉科', '柳杉属', '乔木，高达40 m，胸径可达2 m。大枝近轮生，平展或斜展；小枝细长，常下垂，绿色，枝条中部的叶较长，常向两端逐渐变短。叶钻形略向内弯曲，先端内曲，四边有气孔线，长1~1.5 cm，果枝的叶通常较短，幼树及萌芽枝的叶。雄球花单生叶腋，长椭圆形，集生于小枝上部，成短穗状花序状；雌球花顶生于短枝上。球果圆球形或扁球形；种鳞20左右，鳞背中部或中下部有1个三角状分离的苞鳞尖头，基部宽3~14 mm，能育的种鳞有2粒种子。种子褐色，近椭圆形，扁平，长4~6.5 mm，边缘有窄翅。花期4月；球果10月成熟。', '湖南：永顺县小溪茶园溪，28°46′15″N，110°14′50″E，333 m，2010-10-04，肖艳、徐亮400191143；古丈县高林乡各竹溪，28°39′43″N，110°04′13″E，981 m，2010-11-06，徐亮、周建军、钱凯歌400191159。四川：宜宾老君山，28°41′40″N，103°59′15″E，1863 m，2011-10-15，邓星光、吴阳晨等4002111080；雅安宝兴蜂桶寨邓池沟，30°32′07″N，102°56′27″E，1780 m，2011-09-27，李志强、刘小波等4002111104；峨眉山高桥，28°29′894″ N，103°21′947″ E，2009-10-06，樊云川、王凯4002110902。河南：信阳波尔登公园，31°51′35″N，114°5′28″E，298 m，2012-09-15，王亚平400314221。湖北：神农架坪堑管理所，31°29′44″N，110°05′1″E，1470 m，2010-10-23，丁时东、危文亮400151075。为我国特有树种，产于江西庐山、福建南平及浙江天目山，有数百年的老树。长江以南地区均有栽培，生长良好。', '喜光，喜温凉至温暖湿润的环境，耐寒，耐干旱，喜疏松且排水良好、富含有机质的壤土。播种繁殖，于春季进行。', '树姿雄伟，为优良的庭园树种，可从植或列植。', 19, 'PENDING');  -- 第19页 Cryptomeria fortunei Hooibr. ex Otto et Dietrich
